BEGIN;

CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE "UiLocales" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Locale" varchar(32) NOT NULL,
    "Name" text NOT NULL,
    "IsEnabled" boolean NOT NULL DEFAULT TRUE,
    "IsRightToLeft" boolean NOT NULL DEFAULT FALSE,
    "CatalogVersion" bigint NOT NULL DEFAULT 1,
    CONSTRAINT "PK_UiLocales" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_UiLocales_Locale" UNIQUE ("Locale"),
    CONSTRAINT "CK_UiLocales_Locale" CHECK (length(btrim("Locale")) > 0),
    CONSTRAINT "CK_UiLocales_Name" CHECK (length(btrim("Name")) > 0),
    CONSTRAINT "CK_UiLocales_CatalogVersion" CHECK ("CatalogVersion" > 0)
);

CREATE TABLE "UiTranslationStatusTypes" (
    "Id" smallint NOT NULL,
    "Key" text NOT NULL,
    CONSTRAINT "PK_UiTranslationStatusTypes" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_UiTranslationStatusTypes_Key" UNIQUE ("Key"),
    CONSTRAINT "CK_UiTranslationStatusTypes_Id" CHECK ("Id" BETWEEN 0 AND 255)
);
INSERT INTO "UiTranslationStatusTypes" ("Id", "Key")
VALUES (1, 'missing'), (2, 'generated'), (3, 'reviewed'), (4, 'manual'), (5, 'outdated');

CREATE TABLE "UiTranslationMessages" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Key" varchar(200) NOT NULL,
    "EnglishText" varchar(8192) NOT NULL,
    "Description" varchar(8192),
    "Version" bigint NOT NULL DEFAULT 1,
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_UiTranslationMessages" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_UiTranslationMessages_Key" UNIQUE ("Key"),
    CONSTRAINT "CK_UiTranslationMessages_Key" CHECK (length(btrim("Key")) > 0),
    CONSTRAINT "CK_UiTranslationMessages_EnglishText" CHECK (length(btrim("EnglishText")) > 0),
    CONSTRAINT "CK_UiTranslationMessages_Description" CHECK ("Description" IS NULL OR length(btrim("Description")) > 0),
    CONSTRAINT "CK_UiTranslationMessages_Version" CHECK ("Version" > 0)
);

CREATE TABLE "UiTranslations" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UiLocaleId" bigint NOT NULL,
    "UiTranslationMessageId" bigint NOT NULL,
    "Text" varchar(8192),
    "UiTranslationStatusTypeId" smallint NOT NULL DEFAULT 1,
    "MessageVersion" bigint NOT NULL,
    "Version" bigint NOT NULL DEFAULT 1,
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_UiTranslations" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_UiTranslations_Locale_Message" UNIQUE ("UiLocaleId", "UiTranslationMessageId"),
    CONSTRAINT "FK_UiTranslations_UiLocales" FOREIGN KEY ("UiLocaleId") REFERENCES "UiLocales" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_UiTranslations_Messages" FOREIGN KEY ("UiTranslationMessageId") REFERENCES "UiTranslationMessages" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_UiTranslations_StatusTypes" FOREIGN KEY ("UiTranslationStatusTypeId") REFERENCES "UiTranslationStatusTypes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_UiTranslations_Text" CHECK (
        ("UiTranslationStatusTypeId" = 1 AND "Text" IS NULL)
        OR ("UiTranslationStatusTypeId" <> 1 AND length(btrim("Text")) > 0 AND "Text" IS NOT NULL)),
    CONSTRAINT "CK_UiTranslations_Versions" CHECK ("MessageVersion" > 0 AND "Version" > 0)
);

CREATE TABLE "AccountRoleTypes" (
    "Id" smallint NOT NULL,
    "Key" text NOT NULL,
    CONSTRAINT "PK_AccountRoleTypes" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_AccountRoleTypes_Key" UNIQUE ("Key"),
    CONSTRAINT "CK_AccountRoleTypes_Id" CHECK ("Id" BETWEEN 0 AND 255),
    CONSTRAINT "CK_AccountRoleTypes_Key" CHECK (length(btrim("Key")) > 0)
);
INSERT INTO "AccountRoleTypes" ("Id", "Key")
VALUES
    (1, 'owner'),
    (2, 'user'),
    (3, 'media_manager');

CREATE TABLE "Accounts" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Email" citext NOT NULL,
    "DisplayName" text NOT NULL,
    "AccountRoleTypeId" smallint NOT NULL,
    "IsEnabled" boolean NOT NULL DEFAULT TRUE,
    "MayConfirmSources" boolean NOT NULL DEFAULT FALSE,
    "EmailVerifiedAt" timestamptz,
    "CredentialRevision" bigint NOT NULL DEFAULT 1,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_Accounts" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_Accounts_Email" UNIQUE ("Email"),
    CONSTRAINT "FK_Accounts_AccountRoleTypes" FOREIGN KEY ("AccountRoleTypeId") REFERENCES "AccountRoleTypes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_Accounts_Email" CHECK (length(btrim("Email"::text)) > 0),
    CONSTRAINT "CK_Accounts_DisplayName" CHECK (length(btrim("DisplayName")) > 0),
    CONSTRAINT "CK_Accounts_CredentialRevision" CHECK ("CredentialRevision" >= 1)
);

-- Wizard step and completion.
CREATE TABLE "InstanceSetupState" (
    "Id" bigint NOT NULL,
    "OwnerCreatedAt" timestamptz,
    "SetupStepTypeId" smallint NOT NULL DEFAULT 1,
    "CompletedAt" timestamptz NULL,
    "Version" bigint NOT NULL DEFAULT 1,
    CONSTRAINT "PK_InstanceSetupState" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_InstanceSetupState_Id" CHECK ("Id" = 1),
    CONSTRAINT "CK_InstanceSetupState_Step" CHECK ("SetupStepTypeId" BETWEEN 1 AND 6),
    CONSTRAINT "CK_InstanceSetupState_Version" CHECK ("Version" > 0)
);
INSERT INTO "InstanceSetupState" ("Id") VALUES (1);

CREATE TABLE "Profiles" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "OwnerAccountId" bigint NOT NULL,
    "DisplayName" text NOT NULL,
    "UiLocaleId" bigint NOT NULL,
    "PinHash" text,
    "PinLength" integer NULL,
    "PinFailedCount" integer NOT NULL DEFAULT 0,
    "PinLockedUntil" timestamptz NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_Profiles" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Profiles_Accounts" FOREIGN KEY ("OwnerAccountId") REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Profiles_UiLocales" FOREIGN KEY ("UiLocaleId") REFERENCES "UiLocales" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_Profiles_DisplayName" CHECK (length(btrim("DisplayName")) > 0),
    CONSTRAINT "CK_Profiles_Pin" CHECK (("PinHash" IS NULL) = ("PinLength" IS NULL) AND ("PinLength" IS NULL OR "PinLength" BETWEEN 3 AND 6)),
    CONSTRAINT "CK_Profiles_PinFailedCount" CHECK ("PinFailedCount" BETWEEN 0 AND 4)
);
CREATE INDEX "IX_Profiles_OwnerAccountId" ON "Profiles" ("OwnerAccountId", "Id");

CREATE TABLE "AccountProfiles" (
    "AccountId" bigint NOT NULL,
    "ProfileId" bigint NOT NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_AccountProfiles" PRIMARY KEY ("AccountId", "ProfileId"),
    CONSTRAINT "FK_AccountProfiles_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AccountProfiles_Profiles" FOREIGN KEY ("ProfileId") REFERENCES "Profiles" ("Id") ON DELETE RESTRICT
);
CREATE INDEX "IX_AccountProfiles_ProfileId" ON "AccountProfiles" ("ProfileId", "AccountId");
ALTER TABLE "Profiles"
    ADD CONSTRAINT "FK_Profiles_OwnerAccountProfiles" FOREIGN KEY ("OwnerAccountId", "Id")
    REFERENCES "AccountProfiles" ("AccountId", "ProfileId") ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE "AccountSessions" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
    "AccountId" bigint NOT NULL,
    "ActiveProfileId" bigint,
    "TokenHash" bytea NOT NULL,
    "ExpiresAt" timestamptz NOT NULL,
    "RevokedAt" timestamptz,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "LastSeenAt" timestamptz,
    "CredentialRevision" bigint NOT NULL DEFAULT 1,
    "RotationRevision" bigint NOT NULL DEFAULT 1,
    "RotatedAt" timestamptz,
    CONSTRAINT "PK_AccountSessions" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_AccountSessions_PublicId" UNIQUE ("PublicId"),
    CONSTRAINT "UX_AccountSessions_TokenHash" UNIQUE ("TokenHash"),
    CONSTRAINT "FK_AccountSessions_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AccountSessions_AccountProfiles" FOREIGN KEY ("AccountId", "ActiveProfileId")
        REFERENCES "AccountProfiles" ("AccountId", "ProfileId") ON DELETE RESTRICT,
    CONSTRAINT "CK_AccountSessions_Expiry" CHECK ("ExpiresAt" > "CreatedAt"),
    CONSTRAINT "CK_AccountSessions_Hash" CHECK (octet_length("TokenHash") = 32),
    CONSTRAINT "CK_AccountSessions_Revisions" CHECK ("CredentialRevision" >= 1 AND "RotationRevision" >= 1),
    CONSTRAINT "CK_AccountSessions_Timestamps" CHECK (
        ("RevokedAt" IS NULL OR "RevokedAt" >= "CreatedAt")
        AND ("LastSeenAt" IS NULL OR "LastSeenAt" >= "CreatedAt")
        AND ("RotatedAt" IS NULL OR "RotatedAt" >= "CreatedAt"))
);
CREATE INDEX "IX_AccountSessions_AccountId_ExpiresAt" ON "AccountSessions" ("AccountId", "ExpiresAt");
CREATE INDEX "IX_AccountSessions_Account_Created" ON "AccountSessions" ("AccountId", "CreatedAt" DESC, "Id" DESC);
CREATE INDEX "IX_AccountSessions_Live_Expiry" ON "AccountSessions" ("ExpiresAt", "Id") WHERE "RevokedAt" IS NULL;

CREATE TABLE "Providers" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Key" text NOT NULL,
    "IsEnabled" boolean NOT NULL DEFAULT TRUE,
    "ProtectedSecret" bytea NULL,
    "BaseUrl" varchar(500) NULL CHECK ("BaseUrl" ~ '^https?://[^/?#]+(/[^?#]*)?/$'),
    "ExternalId" varchar(128) NULL,
    "SyncedAt" timestamptz NULL,
    CONSTRAINT "PK_Providers" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_Providers_Key" UNIQUE ("Key")
);
INSERT INTO "Providers" ("Key") VALUES ('plex'), ('tmdb'), ('openlibrary'), ('anilist'), ('musicbrainz'), ('igdb'), ('jellyfin'), ('emby');

CREATE TABLE "AccountPasswords" (
    "AccountId" bigint NOT NULL,
    "PasswordHash" text NOT NULL,
    "ChangedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_AccountPasswords" PRIMARY KEY ("AccountId"),
    CONSTRAINT "FK_AccountPasswords_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_AccountPasswords_Hash" CHECK (length(btrim("PasswordHash")) > 0)
);

CREATE TABLE "AccountPasskeys" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "AccountId" bigint NOT NULL,
    "CredentialId" bytea NOT NULL,
    "PublicKey" bytea NOT NULL,
    "SignatureCounter" bigint NOT NULL DEFAULT 0,
    "Aaguid" uuid,
    "Transports" text[] NOT NULL DEFAULT ARRAY[]::text[],
    "BackupEligible" boolean,
    "BackedUp" boolean,
    "UserVerificationRequired" boolean,
    "DisplayName" varchar(100) NOT NULL DEFAULT 'Passkey',
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "LastUsedAt" timestamptz,
    "RevokedAt" timestamptz,
    CONSTRAINT "PK_AccountPasskeys" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AccountPasskeys_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "UX_AccountPasskeys_CredentialId" UNIQUE ("CredentialId"),
    CONSTRAINT "CK_AccountPasskeys_SignatureCounter" CHECK ("SignatureCounter" >= 0),
    CONSTRAINT "CK_AccountPasskeys_BackupState" CHECK ("BackedUp" IS DISTINCT FROM TRUE OR "BackupEligible" IS TRUE),
    CONSTRAINT "CK_AccountPasskeys_Credential" CHECK (octet_length("CredentialId") BETWEEN 1 AND 1024),
    CONSTRAINT "CK_AccountPasskeys_PublicKey" CHECK (octet_length("PublicKey") BETWEEN 1 AND 16384),
    CONSTRAINT "CK_AccountPasskeys_Name" CHECK (length(btrim("DisplayName")) > 0),
    CONSTRAINT "CK_AccountPasskeys_Timestamps" CHECK (
        ("LastUsedAt" IS NULL OR "LastUsedAt" >= "CreatedAt")
        AND ("RevokedAt" IS NULL OR "RevokedAt" >= "CreatedAt"))
);
CREATE INDEX "IX_AccountPasskeys_AccountId" ON "AccountPasskeys" ("AccountId");

CREATE TABLE "AccountTotpFactors" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "AccountId" bigint NOT NULL,
    "EncryptedSecret" bytea NOT NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "ConfirmedAt" timestamptz,
    "LastAcceptedStep" bigint NOT NULL DEFAULT -1,
    "RevokedAt" timestamptz,
    CONSTRAINT "PK_AccountTotpFactors" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AccountTotpFactors_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_AccountTotpFactors_Secret" CHECK (octet_length("EncryptedSecret") BETWEEN 1 AND 16384),
    CONSTRAINT "CK_AccountTotpFactors_Step" CHECK ("LastAcceptedStep" >= -1),
    CONSTRAINT "CK_AccountTotpFactors_Timestamps" CHECK (
        ("ConfirmedAt" IS NULL OR "ConfirmedAt" >= "CreatedAt")
        AND ("RevokedAt" IS NULL OR "RevokedAt" >= "CreatedAt")
        AND ("LastAcceptedStep" = -1 OR "ConfirmedAt" IS NOT NULL))
);
CREATE INDEX "IX_AccountTotpFactors_Account" ON "AccountTotpFactors" ("AccountId", "Id");

CREATE TABLE "AccountRecoveryCodes" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "AccountId" bigint NOT NULL,
    "CodeHash" bytea NOT NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UsedAt" timestamptz,
    CONSTRAINT "PK_AccountRecoveryCodes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AccountRecoveryCodes_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "UX_AccountRecoveryCodes_AccountId_CodeHash" UNIQUE ("AccountId", "CodeHash"),
    CONSTRAINT "CK_AccountRecoveryCodes_Hash" CHECK (octet_length("CodeHash") = 32),
    CONSTRAINT "CK_AccountRecoveryCodes_Used" CHECK ("UsedAt" IS NULL OR "UsedAt" >= "CreatedAt")
);

CREATE TABLE "AccountExternalLogins" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "AccountId" bigint NOT NULL,
    "ProviderId" bigint NOT NULL,
    "ExternalAccountId" text NOT NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_AccountExternalLogins" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AccountExternalLogins_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AccountExternalLogins_Providers" FOREIGN KEY ("ProviderId") REFERENCES "Providers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "UX_AccountExternalLogins_Provider_ExternalId" UNIQUE ("ProviderId", "ExternalAccountId"),
    CONSTRAINT "UX_AccountExternalLogins_Account_Provider" UNIQUE ("AccountId", "ProviderId"),
    CONSTRAINT "CK_AccountExternalLogins_Identity" CHECK (
        length("ExternalAccountId") BETWEEN 1 AND 200 AND "ExternalAccountId" = btrim("ExternalAccountId"))
);
CREATE INDEX "IX_AccountExternalLogins_AccountId" ON "AccountExternalLogins" ("AccountId");

CREATE TABLE "AuthChallengePurposeTypes" (
    "Id" smallint NOT NULL,
    "Key" text NOT NULL,
    CONSTRAINT "PK_AuthChallengePurposeTypes" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_AuthChallengePurposeTypes_Key" UNIQUE ("Key"),
    CONSTRAINT "CK_AuthChallengePurposeTypes_Id" CHECK ("Id" BETWEEN 0 AND 255),
    CONSTRAINT "CK_AuthChallengePurposeTypes_Key" CHECK (length(btrim("Key")) > 0)
);
INSERT INTO "AuthChallengePurposeTypes" ("Id", "Key")
VALUES
    (1, 'email_verification'),
    (2, 'password_reset'),
    (3, 'totp_enrollment'),
    (4, 'totp_sign_in'),
    (5, 'passkey_enrollment'),
    (6, 'passkey_sign_in'),
    (7, 'external_login'),
    (8, 'external_link'),
    (9, 'provider_media_consent');

CREATE TABLE "AccountAuthChallenges" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
    "AccountId" bigint,
    "AuthChallengePurposeTypeId" smallint NOT NULL,
    "TokenHash" bytea NOT NULL,
    "CredentialRevision" bigint,
    "ProtectedState" bytea,
    "ExpiresAt" timestamptz NOT NULL,
    "ConsumedAt" timestamptz,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_AccountAuthChallenges" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_AccountAuthChallenges_PublicId" UNIQUE ("PublicId"),
    CONSTRAINT "UX_AccountAuthChallenges_TokenHash" UNIQUE ("TokenHash"),
    CONSTRAINT "UX_AccountAuthChallenges_Id_Purpose" UNIQUE ("Id", "AuthChallengePurposeTypeId"),
    CONSTRAINT "FK_AccountAuthChallenges_Accounts" FOREIGN KEY ("AccountId") REFERENCES "Accounts" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AccountAuthChallenges_Purpose" FOREIGN KEY ("AuthChallengePurposeTypeId")
        REFERENCES "AuthChallengePurposeTypes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_AccountAuthChallenges_Account" CHECK (
        ("AccountId" IS NULL AND "CredentialRevision" IS NULL AND "AuthChallengePurposeTypeId" IN (6, 7))
        OR ("AccountId" IS NOT NULL AND "CredentialRevision" IS NOT NULL AND "CredentialRevision" >= 1)),
    CONSTRAINT "CK_AccountAuthChallenges_Hash" CHECK (octet_length("TokenHash") = 32),
    CONSTRAINT "CK_AccountAuthChallenges_State" CHECK (
        "ProtectedState" IS NULL OR octet_length("ProtectedState") BETWEEN 1 AND 16384),
    CONSTRAINT "CK_AccountAuthChallenges_Expiry" CHECK ("ExpiresAt" > "CreatedAt"),
    CONSTRAINT "CK_AccountAuthChallenges_Consumed" CHECK ("ConsumedAt" IS NULL OR "ConsumedAt" >= "CreatedAt")
);
CREATE INDEX "IX_AccountAuthChallenges_Account" ON "AccountAuthChallenges" ("AccountId", "Id") WHERE "ConsumedAt" IS NULL;
CREATE INDEX "IX_AccountAuthChallenges_Expiry" ON "AccountAuthChallenges" ("ExpiresAt", "Id");

CREATE TABLE "AccountExternalAuthFlows" (
    "AccountAuthChallengeId" bigint NOT NULL,
    "AuthChallengePurposeTypeId" smallint NOT NULL,
    "ProviderId" bigint NOT NULL,
    "StartedProfileId" bigint,
    "ExternalPinId" bigint NOT NULL,
    "ClientIdentifier" varchar(200) NOT NULL,
    "VerifiedExternalAccountId" varchar(200),
    "ReturnPath" varchar(2048) NOT NULL DEFAULT '/',
    CONSTRAINT "PK_AccountExternalAuthFlows" PRIMARY KEY ("AccountAuthChallengeId"),
    CONSTRAINT "FK_AccountExternalAuthFlows_ChallengePurpose" FOREIGN KEY ("AccountAuthChallengeId", "AuthChallengePurposeTypeId")
        REFERENCES "AccountAuthChallenges" ("Id", "AuthChallengePurposeTypeId") ON DELETE RESTRICT,
    CONSTRAINT "FK_AccountExternalAuthFlows_Providers" FOREIGN KEY ("ProviderId") REFERENCES "Providers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AccountExternalAuthFlows_Profiles" FOREIGN KEY ("StartedProfileId") REFERENCES "Profiles" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_AccountExternalAuthFlows_Purpose" CHECK (
        ("AuthChallengePurposeTypeId" = 9 AND "StartedProfileId" IS NOT NULL)
        OR ("AuthChallengePurposeTypeId" IN (7, 8) AND "StartedProfileId" IS NULL)),
    CONSTRAINT "CK_AccountExternalAuthFlows_Pin" CHECK ("ExternalPinId" > 0),
    CONSTRAINT "CK_AccountExternalAuthFlows_Client" CHECK (
        length("ClientIdentifier") > 0 AND "ClientIdentifier" = btrim("ClientIdentifier")),
    CONSTRAINT "CK_AccountExternalAuthFlows_Verified" CHECK (
        "VerifiedExternalAccountId" IS NULL OR (length("VerifiedExternalAccountId") > 0
        AND "VerifiedExternalAccountId" = btrim("VerifiedExternalAccountId"))),
    CONSTRAINT "CK_AccountExternalAuthFlows_ReturnPath" CHECK (
        "ReturnPath" LIKE '/%' AND "ReturnPath" NOT LIKE '//%'
        AND position(chr(92) IN "ReturnPath") = 0 AND "ReturnPath" !~ '[[:cntrl:]]')
);
CREATE INDEX "IX_AccountExternalAuthFlows_Provider" ON "AccountExternalAuthFlows" ("ProviderId", "AccountAuthChallengeId");
CREATE INDEX "IX_AccountExternalAuthFlows_Profile" ON "AccountExternalAuthFlows" ("StartedProfileId") WHERE "StartedProfileId" IS NOT NULL;

COMMIT;
